namespace EventRegistration.Api.Models;

public enum RegistrationType
{
    GeneralAdmission,
    ReservedSeating,
}

/// <summary>
/// Order lifecycle. Allowed transitions:
/// PendingCheckout -> PendingPayment -> Confirmed, and
/// PendingCheckout/PendingPayment -> Released (with a reason).
/// Confirmed and Released are terminal.
/// </summary>
public enum OrderStatus
{
    /// <summary>Inventory is held; no Stripe session is known to exist yet.</summary>
    PendingCheckout,

    /// <summary>Inventory is held and a Stripe Checkout session exists that may still accept payment.</summary>
    PendingPayment,

    /// <summary>Payment verified server-side; held inventory converted to sold.</summary>
    Confirmed,

    /// <summary>Held inventory returned to the pool. Never reached from Confirmed.</summary>
    Released,

    /// <summary>
    /// Development-only exception (see docs/contracts/booking-rules.md, "Demo reset"): a Confirmed
    /// test purchase whose payment was verified as fully refunded at Stripe by the demo reset.
    /// Terminal; never confirmed again and never shown as a successful booking.
    /// </summary>
    RefundedByDemoReset,
}

public enum SeatReservationStatus
{
    Held,
    Sold,
    Released,
}

public enum ThemeName
{
    Fall,
    Winter,
}
namespace EventRegistration.Api.Models;

public class Event
{
    public int Id { get; set; }
    public required string Name { get; set; }
    public required string Description { get; set; }
    public required string Venue { get; set; }
    public RegistrationType RegistrationType { get; set; }

    /// <summary>Path of a bundled client image, e.g. "/images/lantern-walk.svg".</summary>
    public string? ImagePath { get; set; }

    public bool Active { get; set; } = true;

    public List<TimeSlot> TimeSlots { get; set; } = [];
    public List<SeatingSection> SeatingSections { get; set; } = [];
}

public class TimeSlot
{
    public int Id { get; set; }
    public int EventId { get; set; }
    public Event? Event { get; set; }
    public DateTime StartUtc { get; set; }
    public DateTime EndUtc { get; set; }
    public bool Active { get; set; } = true;

    public List<SlotInventory> Inventories { get; set; } = [];
}

/// <summary>A General Admission ticket kind (Adult, Child, VIP...). Price is server-owned.</summary>
public class TicketType
{
    public int Id { get; set; }
    public int EventId { get; set; }
    public Event? Event { get; set; }
    public required string Name { get; set; }
    public required string Description { get; set; }
    public int PriceCents { get; set; }
    public bool Active { get; set; } = true;
}

/// <summary>
/// Independent capacity for one (time slot, ticket type) pair.
/// Invariant: 0 &lt;= Reserved, 0 &lt;= Sold, Reserved + Sold &lt;= Capacity.
/// Changes are made only with guarded conditional UPDATE statements (see InventoryService).
/// </summary>
public class SlotInventory
{
    public int Id { get; set; }
    public int TimeSlotId { get; set; }
    public TimeSlot? TimeSlot { get; set; }
    public int TicketTypeId { get; set; }
    public TicketType? TicketType { get; set; }
    public int Capacity { get; set; }
    public int Reserved { get; set; }
    public int Sold { get; set; }
}

public class SiteSettings
{
    public int Id { get; set; }
    public ThemeName ActiveTheme { get; set; } = ThemeName.Fall;
}
namespace EventRegistration.Api.Models;

public class Order
{
    /// <summary>Random GUID; acts as the unguessable order reference (there are no accounts).</summary>
    public Guid Id { get; set; }

    public int EventId { get; set; }
    public int TimeSlotId { get; set; }
    public RegistrationType RegistrationType { get; set; }
    public OrderStatus Status { get; set; }
    public string? ReleaseReason { get; set; }

    /// <summary>Client-supplied Idempotency-Key header of the POST that created this order.</summary>
    public required string RequestIdempotencyKey { get; set; }

    /// <summary>Normalized selection, used to reject reuse of a key with a different selection.</summary>
    public required string RequestFingerprint { get; set; }

    public string Currency { get; set; } = "usd";
    public long TotalCents { get; set; }
    public string? CustomerEmail { get; set; }

    public DateTime CreatedUtc { get; set; }

    /// <summary>After this time an order that never attempted checkout may be released.</summary>
    public DateTime PreCheckoutHoldExpiresUtc { get; set; }

    /// <summary>
    /// Set when a Stripe session creation call starts. While set and no session is stored,
    /// the outcome is uncertain and the hold must not be released without asking Stripe.
    /// </summary>
    public DateTime? CheckoutAttemptStartedUtc { get; set; }

    /// <summary>Expiry sent to Stripe; fixed on the first attempt so retries send an identical payload.</summary>
    public DateTime? PlannedSessionExpiresUtc { get; set; }

    public string? StripeSessionId { get; set; }
    public string? StripeCheckoutUrl { get; set; }
    public DateTime? StripeSessionExpiresUtc { get; set; }

    public DateTime? ConfirmedUtc { get; set; }
    public DateTime? ReleasedUtc { get; set; }

    public List<OrderItem> Items { get; set; } = [];

    /// <summary>Stable key sent to Stripe so a retried creation returns the same session.</summary>
    public string StripeIdempotencyKey => $"blevinspass-order-{Id:N}-checkout";
}

public class OrderItem
{
    public int Id { get; set; }
    public Guid OrderId { get; set; }

    /// <summary>Set for General Admission lines.</summary>
    public int? TicketTypeId { get; set; }

    /// <summary>Set for Reserved Seating lines (one seat per line).</summary>
    public int? SeatId { get; set; }

    /// <summary>Snapshot of what was bought, e.g. "Adult" or "VIP Center A-01".</summary>
    public required string Description { get; set; }
    public int Quantity { get; set; }

    /// <summary>Server price snapshot at hold time.</summary>
    public int UnitPriceCents { get; set; }
}
namespace EventRegistration.Api.Models;

public class SeatingSection
{
    public int Id { get; set; }
    public int EventId { get; set; }
    public Event? Event { get; set; }

    /// <summary>Stable code used in seat identifiers, e.g. "VIP-CENTER".</summary>
    public required string Code { get; set; }
    public required string Name { get; set; }
    public int PriceCents { get; set; }
    public int DisplayOrder { get; set; }

    public List<Seat> Seats { get; set; } = [];
}

/// <summary>A physical seat. The same seat is reused for every performance of its event.</summary>
public class Seat
{
    public int Id { get; set; }
    public int SeatingSectionId { get; set; }
    public SeatingSection? SeatingSection { get; set; }

    /// <summary>Human-readable identifier, e.g. "VIP-CENTER-A-01".</summary>
    public required string Label { get; set; }
    public required string Row { get; set; }
    public int SeatNumber { get; set; }
    public int SvgX { get; set; }
    public int SvgY { get; set; }
    public bool Active { get; set; } = true;
}

/// <summary>
/// A claim on one seat for one performance. At most one Held or Sold reservation may exist
/// per (TimeSlotId, SeatId); a filtered unique index enforces this so Released history
/// does not block rebooking.
/// </summary>
public class SeatReservation
{
    public int Id { get; set; }
    public int TimeSlotId { get; set; }
    public int SeatId { get; set; }
    public Seat? Seat { get; set; }
    public Guid OrderId { get; set; }
    public SeatReservationStatus Status { get; set; }
}
using EventRegistration.Api.Models;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Storage.ValueConversion;

namespace EventRegistration.Api.Data;

public class AppDbContext(DbContextOptions<AppDbContext> options) : DbContext(options)
{
    public DbSet<Event> Events => Set<Event>();
    public DbSet<TimeSlot> TimeSlots => Set<TimeSlot>();
    public DbSet<TicketType> TicketTypes => Set<TicketType>();
    public DbSet<SlotInventory> SlotInventories => Set<SlotInventory>();
    public DbSet<SeatingSection> SeatingSections => Set<SeatingSection>();
    public DbSet<Seat> Seats => Set<Seat>();
    public DbSet<SeatReservation> SeatReservations => Set<SeatReservation>();
    public DbSet<Order> Orders => Set<Order>();
    public DbSet<OrderItem> OrderItems => Set<OrderItem>();
    public DbSet<SiteSettings> SiteSettings => Set<SiteSettings>();

    protected override void ConfigureConventions(ModelConfigurationBuilder configurationBuilder)
    {
        // SQLite has no native date type and loses DateTimeKind. Everything is stored as UTC,
        // so mark values read back as UTC; the API then serializes them with a trailing "Z".
        configurationBuilder.Properties<DateTime>().HaveConversion<UtcDateTimeConverter>();
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Event>().Property(e => e.RegistrationType).HasConversion<string>();

        modelBuilder.Entity<TicketType>()
            .ToTable(t => t.HasCheckConstraint("CK_TicketType_Price", "\"PriceCents\" >= 0"));

        modelBuilder.Entity<SlotInventory>(entity =>
        {
            entity.HasIndex(i => new { i.TimeSlotId, i.TicketTypeId }).IsUnique();
            entity.ToTable(t => t.HasCheckConstraint(
                "CK_SlotInventory_Counts",
                "\"Reserved\" >= 0 AND \"Sold\" >= 0 AND \"Reserved\" + \"Sold\" <= \"Capacity\""));
        });

        modelBuilder.Entity<SeatingSection>().HasIndex(s => new { s.EventId, s.Code }).IsUnique();
        modelBuilder.Entity<Seat>().HasIndex(s => s.Label).IsUnique();

        modelBuilder.Entity<SeatReservation>(entity =>
        {
            entity.Property(r => r.Status).HasConversion<string>();
            // Only live claims are unique, so released history never blocks rebooking a seat.
            entity.HasIndex(r => new { r.TimeSlotId, r.SeatId })
                .IsUnique()
                .HasFilter("\"Status\" IN ('Held', 'Sold')")
                .HasDatabaseName("IX_SeatReservation_LiveClaim");
            entity.HasIndex(r => r.OrderId);
        });

        modelBuilder.Entity<Order>(entity =>
        {
            entity.Property(o => o.Status).HasConversion<string>();
            entity.Property(o => o.RegistrationType).HasConversion<string>();
            entity.HasIndex(o => o.RequestIdempotencyKey).IsUnique();
            entity.HasIndex(o => o.StripeSessionId).IsUnique();
            entity.HasIndex(o => o.Status);
            entity.Ignore(o => o.StripeIdempotencyKey);
            entity.HasMany(o => o.Items).WithOne().HasForeignKey(i => i.OrderId);
        });

        modelBuilder.Entity<SiteSettings>().Property(s => s.ActiveTheme).HasConversion<string>();
    }
}

public sealed class UtcDateTimeConverter() : ValueConverter<DateTime, DateTime>(
    value => value.Kind == DateTimeKind.Utc ? value : value.ToUniversalTime(),
    value => DateTime.SpecifyKind(value, DateTimeKind.Utc));
using EventRegistration.Api.Data;
using EventRegistration.Api.DTOs;
using EventRegistration.Api.Services;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;

var builder = WebApplication.CreateBuilder(args);

// One SQLite file, anchored to the API project folder (content root) regardless of the working directory.
var connectionString = new SqliteConnectionStringBuilder(builder.Configuration.GetConnectionString("BlevinsPass"));
connectionString.DataSource = Path.Combine(builder.Environment.ContentRootPath, connectionString.DataSource);
connectionString.DefaultTimeout = 30; // seconds to wait on a locked database before failing
builder.Services.AddDbContext<AppDbContext>(options => options.UseSqlite(connectionString.ToString()));

builder.Services.Configure<CheckoutOptions>(builder.Configuration.GetSection("Checkout"));
builder.Services.AddSingleton(TimeProvider.System);
builder.Services.AddSingleton<ICheckoutGateway, StripeCheckoutGateway>();
builder.Services.AddScoped<InventoryService>();
builder.Services.AddScoped<PaymentService>();
builder.Services.AddScoped<OrderService>();
builder.Services.AddScoped<CatalogService>();
builder.Services.Configure<DemoResetOptions>(builder.Configuration.GetSection("DemoReset"));
builder.Services.AddSingleton<BookingOperationGate>();
builder.Services.AddScoped<DemoResetService>();

builder.Services.AddControllers().ConfigureApiBehaviorOptions(options =>
{
    // Malformed bodies (e.g. a quantity of 1.5) use the same error shape as business validation.
    options.InvalidModelStateResponseFactory = context =>
    {
        var firstError = context.ModelState.Values.SelectMany(v => v.Errors).FirstOrDefault()?.ErrorMessage;
        return new BadRequestObjectResult(new ApiErrorBody(new ApiError(
            "validation_failed",
            string.IsNullOrWhiteSpace(firstError) ? "The request body is invalid." : firstError)));
    };
});

var app = builder.Build();

using (var scope = app.Services.CreateScope())
{
    var db = scope.ServiceProvider.GetRequiredService<AppDbContext>();
    // EnsureCreated (no migrations) suits this disposable demo. To reset, stop the API and delete blevinspass.db*.
    await db.Database.EnsureCreatedAsync();
    await SeedData.EnsureSeededAsync(db, DateTime.UtcNow);
}

app.UseMiddleware<BookingExceptionMiddleware>();
app.MapControllers();

app.Run();

