using EventRegistration.Api.Data;
using EventRegistration.Api.DTOs;
using EventRegistration.Api.Models;
using Microsoft.EntityFrameworkCore;

namespace EventRegistration.Api.Services;

/// <summary>Read-only event, availability and seating queries, plus the persisted theme setting.</summary>
public class CatalogService(AppDbContext db, PaymentService payments, TimeProvider clock)
{
    private DateTime UtcNow => clock.GetUtcNow().UtcDateTime;

    public async Task<IReadOnlyList<EventSummaryDto>> GetEventsAsync(CancellationToken cancellationToken)
    {
        var events = await db.Events.AsNoTracking()
            .Where(e => e.Active)
            .Include(e => e.TimeSlots)
            .Include(e => e.SeatingSections)
            .ToListAsync(cancellationToken);
        var ticketPrices = await db.TicketTypes.AsNoTracking()
            .Where(t => t.Active)
            .Select(t => new { t.EventId, t.PriceCents })
            .ToListAsync(cancellationToken);

        return events
            .Select(e => ToSummary(e, e.RegistrationType == RegistrationType.GeneralAdmission
                ? ticketPrices.Where(p => p.EventId == e.Id).Select(p => (int?)p.PriceCents).Min()
                : e.SeatingSections.Select(s => (int?)s.PriceCents).Min()))
            .OrderBy(e => e.TimeSlots.FirstOrDefault()?.StartUtc)
            .ToList();
    }

    public async Task<EventSummaryDto> GetEventAsync(int eventId, CancellationToken cancellationToken)
    {
        var events = await GetEventsAsync(cancellationToken);
        return events.FirstOrDefault(e => e.Id == eventId) ?? throw BookingException.NotFound("Event not found.");
    }

    public async Task<SlotAvailabilityDto> GetTicketAvailabilityAsync(int eventId, int timeSlotId, CancellationToken cancellationToken)
    {
        var slot = await GetSlotAsync(eventId, timeSlotId, RegistrationType.GeneralAdmission, cancellationToken);
        await payments.ReconcileStaleOrdersAsync(slot.Id, cancellationToken);

        var ticketTypes = await db.SlotInventories.AsNoTracking()
            .Where(i => i.TimeSlotId == slot.Id && i.TicketType!.Active)
            .OrderBy(i => i.TicketType!.PriceCents)
            .Select(i => new TicketAvailabilityDto(
                i.TicketTypeId,
                i.TicketType!.Name,
                i.TicketType.Description,
                i.TicketType.PriceCents,
                i.Capacity,
                i.Capacity - i.Reserved - i.Sold))
            .ToListAsync(cancellationToken);

        return new SlotAvailabilityDto(eventId, slot.Id, "usd", IsBookable(slot), ticketTypes);
    }

    public async Task<SeatingChartDto> GetSeatingChartAsync(int eventId, CancellationToken cancellationToken)
    {
        var sections = await db.SeatingSections.AsNoTracking()
            .Where(s => s.EventId == eventId)
            .OrderBy(s => s.DisplayOrder)
            .Include(s => s.Seats)
            .ToListAsync(cancellationToken);
        if (sections.Count == 0)
        {
            throw BookingException.NotFound("This event has no seating chart.");
        }

        return new SeatingChartDto(eventId, "usd", sections
            .Select(s => new SeatingSectionDto(s.Id, s.Code, s.Name, s.PriceCents, s.Seats
                .OrderBy(seat => seat.Row).ThenBy(seat => seat.SeatNumber)
                .Select(seat => new SeatDto(seat.Id, seat.Label, seat.Row, seat.SeatNumber, seat.SvgX, seat.SvgY, seat.Active))
                .ToList()))
            .ToList());
    }

    public async Task<SeatingAvailabilityDto> GetSeatingAvailabilityAsync(int eventId, int timeSlotId, CancellationToken cancellationToken)
    {
        var slot = await GetSlotAsync(eventId, timeSlotId, RegistrationType.ReservedSeating, cancellationToken);
        await payments.ReconcileStaleOrdersAsync(slot.Id, cancellationToken);

        var seats = await db.Seats.AsNoTracking()
            .Where(s => s.SeatingSection!.EventId == eventId)
            .Select(s => new { s.Id, s.Active, s.SeatingSectionId })
            .ToListAsync(cancellationToken);
        var liveClaims = await db.SeatReservations.AsNoTracking()
            .Where(r => r.TimeSlotId == slot.Id && (r.Status == SeatReservationStatus.Held || r.Status == SeatReservationStatus.Sold))
            .ToDictionaryAsync(r => r.SeatId, r => (SeatReservationStatus?)r.Status, cancellationToken);

        var seatStatuses = seats
            .Select(seat => new SeatStatusDto(seat.Id, DescribeSeat(seat.Active, liveClaims.GetValueOrDefault(seat.Id))))
            .ToList();

        // Section counts are derived from seat states; there is no separate quantity ledger to drift.
        var sectionCounts = seats
            .GroupBy(s => s.SeatingSectionId)
            .Select(group => new SectionRemainingDto(
                group.Key,
                group.Count(s => seatStatuses.First(status => status.SeatId == s.Id).Status == "available"),
                group.Count()))
            .ToList();

        return new SeatingAvailabilityDto(eventId, slot.Id, IsBookable(slot), seatStatuses, sectionCounts);
    }

    public async Task<ThemeDto> GetThemeAsync()
    {
        var settings = await db.SiteSettings.AsNoTracking().FirstAsync();
        return new ThemeDto(settings.ActiveTheme.ToString());
    }

    public async Task<ThemeDto> SetThemeAsync(string? themeName)
    {
        if (!Enum.TryParse<ThemeName>(themeName, ignoreCase: true, out var theme) || !Enum.IsDefined(theme))
        {
            throw BookingException.Validation("activeTheme must be \"Fall\" or \"Winter\".");
        }
        var settings = await db.SiteSettings.FirstAsync();
        settings.ActiveTheme = theme;
        await db.SaveChangesAsync();
        return new ThemeDto(theme.ToString());
    }

    private async Task<TimeSlot> GetSlotAsync(int eventId, int timeSlotId, RegistrationType expectedType, CancellationToken cancellationToken)
    {
        var slot = await db.TimeSlots.AsNoTracking().Include(s => s.Event)
            .FirstOrDefaultAsync(s => s.Id == timeSlotId && s.EventId == eventId, cancellationToken)
            ?? throw BookingException.NotFound("That time slot does not exist for this event.");
        if (slot.Event!.RegistrationType != expectedType)
        {
            throw BookingException.Validation(expectedType == RegistrationType.ReservedSeating
                ? "This event does not use reserved seating."
                : "This event uses reserved seating; use the seating availability endpoint.");
        }
        return slot;
    }

    private static string DescribeSeat(bool active, SeatReservationStatus? liveClaim) => (active, liveClaim) switch
    {
        (false, _) => "inactive",
        (_, SeatReservationStatus.Sold) => "sold",
        (_, SeatReservationStatus.Held) => "held",
        _ => "available",
    };

    private bool IsBookable(TimeSlot slot) => slot.Active && slot.StartUtc > UtcNow;

    private EventSummaryDto ToSummary(Event e, int? fromPriceCents) => new(
        e.Id,
        e.Name,
        e.Description,
        e.Venue,
        e.RegistrationType.ToString(),
        e.ImagePath,
        fromPriceCents,
        e.TimeSlots
            .Where(s => s.Active)
            .OrderBy(s => s.StartUtc)
            .Select(s => new TimeSlotDto(s.Id, s.StartUtc, s.EndUtc, IsBookable(s)))
            .ToList());
}
using EventRegistration.Api.Models;
using Microsoft.EntityFrameworkCore;

namespace EventRegistration.Api.Data;

/// <summary>
/// Idempotent startup seed. Runs only when the database has no events, so restarting the API
/// never resets purchases or settings. Dates are relative to the first initialization.
/// </summary>
public static class SeedData
{
    private static readonly TimeZoneInfo VenueTimeZone = FindVenueTimeZone();

    /// <summary>IANA id works on Linux/macOS and modern Windows (ICU); the Windows id is a fallback.</summary>
    private static TimeZoneInfo FindVenueTimeZone()
    {
        try
        {
            return TimeZoneInfo.FindSystemTimeZoneById("America/New_York");
        }
        catch (TimeZoneNotFoundException)
        {
            return TimeZoneInfo.FindSystemTimeZoneById("Eastern Standard Time");
        }
    }

    public static async Task EnsureSeededAsync(AppDbContext db, DateTime utcNow)
    {
        if (!await db.SiteSettings.AnyAsync())
        {
            db.SiteSettings.Add(new SiteSettings { Id = 1, ActiveTheme = ThemeName.Fall });
            await db.SaveChangesAsync();
        }

        if (await db.Events.AnyAsync())
        {
            return;
        }

        // First event day is one week out (venue-local date) so every seeded slot is in the future.
        var firstDay = TimeZoneInfo.ConvertTimeFromUtc(utcNow, VenueTimeZone).Date.AddDays(7);

        AddGeneralAdmissionEvent(db, firstDay.AddDays(0),
            "Harvest Lantern Walk",
            "A guided evening stroll through the orchard by lantern light, with cider at the barn.",
            "Brushfire Orchard Trail", "/images/lantern-walk.svg",
            slotStarts: [(17, 0), (19, 0)], durationMinutes: 90,
            tickets: [("Adult", "Ages 13 and up", 2400, 20), ("Child", "Ages 3-12", 1200, 15)]);

        AddGeneralAdmissionEvent(db, firstDay.AddDays(2),
            "Pumpkin Patch Hayride",
            "Ride the wagon to the patch and pick your own pumpkin to take home.",
            "Brushfire Farm Fields", "/images/hayride.svg",
            slotStarts: [(10, 0), (13, 0), (15, 30)], durationMinutes: 75,
            tickets: [("Adult", "Ages 13 and up", 1800, 25), ("Child", "Ages 3-12", 1000, 25), ("Family Wagon", "Private wagon seating for up to 5", 6500, 3)]);

        AddGeneralAdmissionEvent(db, firstDay.AddDays(5),
            "Orchard Cider Tasting",
            "Sample small-batch ciders paired with local cheese in the cellar barn. 21+.",
            "Cellar Barn", "/images/cider.svg",
            slotStarts: [(14, 0), (18, 0)], durationMinutes: 120,
            tickets: [("General Admission", "Five tasting pours", 3000, 30), ("VIP", "Reserved table and a take-home bottle", 5500, 2)]);

        AddGeneralAdmissionEvent(db, firstDay.AddDays(9),
            "Winter Market & Skating",
            "Browse the holiday makers' market and skate the pond rink. Skate rental included.",
            "Village Green", "/images/market.svg",
            slotStarts: [(11, 0), (15, 0)], durationMinutes: 180,
            tickets: [("Adult", "Ages 13 and up", 2000, 40), ("Child", "Ages 3-12", 1200, 30)]);

        AddGeneralAdmissionEvent(db, firstDay.AddDays(12),
            "Snowlight Forest Trail",
            "A mile-long woodland trail glowing with thousands of lights and warming fires.",
            "North Woods", "/images/forest-trail.svg",
            slotStarts: [(17, 30), (19, 30)], durationMinutes: 90,
            tickets: [("General Admission", "Timed trail entry", 2600, 35), ("VIP Fireside", "Trail entry plus reserved fire pit and cocoa", 4800, 6)]);

        AddWinterLightsConcert(db, firstDay.AddDays(14));

        await db.SaveChangesAsync();
    }

    private static void AddGeneralAdmissionEvent(
        AppDbContext db,
        DateTime localDay,
        string name,
        string description,
        string venue,
        string imagePath,
        (int Hour, int Minute)[] slotStarts,
        int durationMinutes,
        (string Name, string Description, int PriceCents, int Capacity)[] tickets)
    {
        var newEvent = new Event
        {
            Name = name,
            Description = description,
            Venue = venue,
            ImagePath = imagePath,
            RegistrationType = RegistrationType.GeneralAdmission,
        };
        db.Events.Add(newEvent);

        var ticketTypes = tickets
            .Select(t => new TicketType { Event = newEvent, Name = t.Name, Description = t.Description, PriceCents = t.PriceCents })
            .ToList();
        db.TicketTypes.AddRange(ticketTypes);

        foreach (var (hour, minute) in slotStarts)
        {
            var startUtc = VenueLocalToUtc(localDay.AddHours(hour).AddMinutes(minute));
            var slot = new TimeSlot { StartUtc = startUtc, EndUtc = startUtc.AddMinutes(durationMinutes) };
            for (var index = 0; index < tickets.Length; index++)
            {
                slot.Inventories.Add(new SlotInventory { TicketType = ticketTypes[index], Capacity = tickets[index].Capacity });
            }
            newEvent.TimeSlots.Add(slot);
        }
    }

    private static void AddWinterLightsConcert(AppDbContext db, DateTime localDay)
    {
        var concert = new Event
        {
            Name = "Winter Lights Concert",
            Description = "An intimate candlelit chamber concert of seasonal favorites. Reserved seating: choose your seats.",
            Venue = "Evergreen Hall",
            ImagePath = "/images/concert.svg",
            RegistrationType = RegistrationType.ReservedSeating,
        };

        foreach (var hour in new[] { 15, 19 })
        {
            var startUtc = VenueLocalToUtc(localDay.AddHours(hour));
            concert.TimeSlots.Add(new TimeSlot { StartUtc = startUtc, EndUtc = startUtc.AddMinutes(100) });
        }

        // 18 physical seats: three sections, two rows (A, B) of three seats each.
        // SVG coordinates match the client chart's 600 x 340 viewBox.
        concert.SeatingSections.Add(CreateSection("ORCHESTRA-LEFT", "Orchestra Left", 8500, 1, originX: 60, originY: 200));
        concert.SeatingSections.Add(CreateSection("VIP-CENTER", "VIP Center", 12500, 2, originX: 240, originY: 120));
        concert.SeatingSections.Add(CreateSection("ORCHESTRA-RIGHT", "Orchestra Right", 8500, 3, originX: 420, originY: 200));

        db.Events.Add(concert);
    }

    private static SeatingSection CreateSection(string code, string name, int priceCents, int displayOrder, int originX, int originY)
    {
        var section = new SeatingSection { Code = code, Name = name, PriceCents = priceCents, DisplayOrder = displayOrder };
        string[] rows = ["A", "B"];
        for (var rowIndex = 0; rowIndex < rows.Length; rowIndex++)
        {
            for (var seatNumber = 1; seatNumber <= 3; seatNumber++)
            {
                section.Seats.Add(new Seat
                {
                    Label = $"{code}-{rows[rowIndex]}-{seatNumber:00}",
                    Row = rows[rowIndex],
                    SeatNumber = seatNumber,
                    SvgX = originX + 30 + (seatNumber - 1) * 40,
                    SvgY = originY + 30 + rowIndex * 44,
                });
            }
        }
        return section;
    }

    private static DateTime VenueLocalToUtc(DateTime venueLocal) =>
        TimeZoneInfo.ConvertTimeToUtc(DateTime.SpecifyKind(venueLocal, DateTimeKind.Unspecified), VenueTimeZone);
}
namespace EventRegistration.Api.DTOs;

/// <summary>
/// Outcome of a development demo reset. Completed=false means local availability was NOT changed;
/// Blockers say why, and RefundedOrders reports any refunds already made at Stripe (which cannot
/// be undone). Retrying is safe: refunds are idempotent and already-refunded payments are a no-op.
/// </summary>
public record DemoResetResultDto(
    bool Completed,
    string Message,
    IReadOnlyList<DemoResetRefundDto> RefundedOrders,
    int ReleasedPendingOrders,
    IReadOnlyList<DemoResetBlockerDto> Blockers);

public record DemoResetRefundDto(
    Guid OrderId,
    string CheckoutSessionId,
    string PaymentIntentId,
    IReadOnlyList<string> RefundIds,
    long AmountRefundedCents,
