  quantity: number;
  unitPriceCents: number;
  lineTotalCents: number;
}

export interface Order {
  id: string;
  eventId: number;
  eventName: string;
  timeSlotId: number;
  slotStartUtc: string;
  registrationType: RegistrationType;
  status: OrderStatus;
  releaseReason: string | null;
  currency: string;
  totalCents: number;
  customerEmail: string | null;
  paymentDeadlineUtc: string | null;
  items: OrderItem[];
}

export interface CheckoutSession {
  orderId: string;
  checkoutUrl: string;
  expiresUtc: string;
}

export type CreateOrderRequest =
  | { timeSlotId: number; tickets: { ticketTypeId: number; quantity: number }[] }
  | { timeSlotId: number; seatIds: number[] };

/** Development demo reset outcome (POST /api/dev/demo-reset). */
export interface DemoResetResult {
  completed: boolean;
  message: string;
  refundedOrders: { orderId: string; checkoutSessionId: string; paymentIntentId: string; refundIds: string[]; amountRefundedCents: number; providerStatus: string }[];
  releasedPendingOrders: number;
  blockers: { orderId: string; reason: string }[];
}
import type {
  CheckoutSession,
  CreateOrderRequest,
  DemoResetResult,
  EventSummary,
  Order,
  SeatingAvailability,
  SeatingChart,
  SlotAvailability,
  ThemeName,
} from '../types/api';

/** An API failure carrying the server's structured error code and HTTP status. */
export class ApiError extends Error {
  readonly status: number;
  readonly code: string;

  constructor(status: number, code: string, message: string) {
    super(message);
    this.status = status;
    this.code = code;
  }
}

async function request<T>(path: string, init?: RequestInit): Promise<T> {
  let response: Response;
  try {
    response = await fetch(path, {
      ...init,
      headers: { 'Content-Type': 'application/json', ...init?.headers },
    });
  } catch {
    throw new ApiError(0, 'network_error', 'Cannot reach the Blevins Pass server. Is the API running?');
  }

  if (!response.ok) {
    const body = (await response.json().catch(() => null)) as { error?: { code: string; message: string } } | null;
    throw new ApiError(
      response.status,
      body?.error?.code ?? 'http_error',
      body?.error?.message ?? `Request failed (${response.status}).`,
    );
  }
  return (await response.json()) as T;
}

export const api = {
  getEvents: () => request<EventSummary[]>('/api/events'),
  getAvailability: (eventId: number, timeSlotId: number) =>
    request<SlotAvailability>(`/api/events/${eventId}/availability?timeSlotId=${timeSlotId}`),
  getSeatingChart: (eventId: number) => request<SeatingChart>(`/api/events/${eventId}/seating`),
  getSeatingAvailability: (eventId: number, timeSlotId: number) =>
    request<SeatingAvailability>(`/api/events/${eventId}/seating/availability?timeSlotId=${timeSlotId}`),
  createOrder: (body: CreateOrderRequest, idempotencyKey: string) =>
    request<Order>('/api/orders', {
      method: 'POST',
      body: JSON.stringify(body),
      headers: { 'Idempotency-Key': idempotencyKey },
    }),
  startCheckout: (orderId: string) => request<CheckoutSession>(`/api/orders/${orderId}/checkout`, { method: 'POST' }),
  confirmOrder: (orderId: string, cancel: boolean) =>
    request<Order>(`/api/orders/${orderId}/confirm`, { method: 'POST', body: JSON.stringify({ cancel }) }),
  /** Development-only; the API answers 404 unless Development + DemoReset:Enabled on loopback. */
  resetDemo: async (): Promise<DemoResetResult> => {
    // The API also checks the Origin header (sent by the browser) against the local app.
    const response = await fetch('/api/dev/demo-reset', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'X-Demo-Reset': 'confirm' },
      body: JSON.stringify({ confirm: true }),
    });
    const body = (await response.json().catch(() => null)) as (DemoResetResult & { error?: { message: string } }) | null;
    if (response.ok && body) return body;
    if (response.status === 409 && body?.blockers) return body; // honest "not reset" result with reasons
    throw new ApiError(response.status, 'demo_reset_failed', body?.error?.message ?? `Reset failed (${response.status}).`);
  },
  getTheme: () => request<{ activeTheme: ThemeName }>('/api/settings/theme'),
  setTheme: (activeTheme: ThemeName) =>
    request<{ activeTheme: ThemeName }>('/api/settings/theme', { method: 'PUT', body: JSON.stringify({ activeTheme }) }),
};
// Display helpers. All event times are shown in venue time (America/New_York).
export const VENUE_TIME_ZONE = 'America/New_York';

const currency = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' });

export function formatCents(cents: number): string {
  return currency.format(cents / 100);
}

export function formatTime(isoUtc: string): string {
  return new Date(isoUtc).toLocaleTimeString('en-US', { timeZone: VENUE_TIME_ZONE, hour: 'numeric', minute: '2-digit' });
}

export function formatLongDate(isoUtc: string): string {
  return new Date(isoUtc).toLocaleDateString('en-US', {
    timeZone: VENUE_TIME_ZONE,
    weekday: 'long',
    month: 'long',
    day: 'numeric',
    year: 'numeric',
  });
}

/** "YYYY-MM-DD" of the instant in venue time; used as the calendar's day key. */
export function venueDateKey(isoUtc: string): string {
  return new Date(isoUtc).toLocaleDateString('en-CA', { timeZone: VENUE_TIME_ZONE });
}
import { createContext, useContext, type Dispatch } from 'react';
import type {
  EventSummary,
  Order,
  SeatingAvailability,
  SeatingChart,
  SlotAvailability,
  ThemeName,
} from '../types/api';

/**
 * The single shared client state. The server remains the authority for prices and inventory;
 * everything here is a display copy that is refreshed after conflicts and purchases.
 */
export interface AppState {
  events: EventSummary[];
  eventsStatus: 'loading' | 'ready' | 'error';
  eventsError: string | null;

  theme: ThemeName;

  selectedEventId: number | null;
  selectedSlotId: number | null;

  availability: SlotAvailability | null;
  seatingChart: SeatingChart | null;
  seatingAvailability: SeatingAvailability | null;
  availabilityStatus: 'idle' | 'loading' | 'ready' | 'error';
  availabilityError: string | null;
  /** Bumped to force an availability reload (after a conflict or purchase). */
  availabilityVersion: number;

  /** General Admission selection: ticketTypeId -> quantity. */
  ticketQuantities: Record<number, number>;
  /** Reserved Seating selection. */
  selectedSeatIds: number[];

  view: 'browse' | 'review' | 'confirmation';
  checkout: CheckoutState;
}

export interface CheckoutState {
  status: 'idle' | 'submitting' | 'redirecting' | 'verifying' | 'error';
  /** Reused for retries of the same review so the server never creates a duplicate order. */
  idempotencyKey: string | null;
  order: Order | null;
  error: string | null;
  /** Order being verified after the Stripe redirect; kept so a failed verification can be retried. */
  returnOrderId: string | null;
}

export type AppAction =
  | { type: 'eventsLoaded'; events: EventSummary[] }
  | { type: 'eventsFailed'; error: string }
  | { type: 'themeChanged'; theme: ThemeName }
  | { type: 'eventSelected'; eventId: number }
  | { type: 'slotSelected'; slotId: number }
  | { type: 'availabilityLoading' }
  | { type: 'availabilityLoaded'; availability: SlotAvailability }
  | { type: 'seatingLoaded'; chart: SeatingChart; availability: SeatingAvailability }
  | { type: 'availabilityFailed'; error: string }
  | { type: 'availabilityRefreshRequested' }
  | { type: 'ticketQuantityChanged'; ticketTypeId: number; quantity: number }
  | { type: 'seatToggled'; seatId: number }
  | { type: 'reviewOpened' }
  | { type: 'reviewClosed' }
  | { type: 'checkoutSubmitting' }
  | { type: 'checkoutRedirecting'; order: Order }
  | { type: 'checkoutFailed'; error: string; conflict: boolean }
  | { type: 'returnVerifying'; orderId: string }
  | { type: 'returnVerified'; order: Order }
  | { type: 'bookingReset' }
  /** Server availability was reset: drop stale selections/checkout, keep theme and catalog, reload counts. */
  | { type: 'demoAvailabilityReset' };

export const initialState: AppState = {
  events: [],
  eventsStatus: 'loading',
  eventsError: null,
  theme: 'Fall',
  selectedEventId: null,
  selectedSlotId: null,
  availability: null,
  seatingChart: null,
  seatingAvailability: null,
  availabilityStatus: 'idle',
  availabilityError: null,
  availabilityVersion: 0,
  ticketQuantities: {},
  selectedSeatIds: [],
  view: 'browse',
  checkout: { status: 'idle', idempotencyKey: null, order: null, error: null, returnOrderId: null },
};

const idleCheckout: CheckoutState = initialState.checkout;

function newIdempotencyKey(): string {
  return crypto.randomUUID();
}

export function appReducer(state: AppState, action: AppAction): AppState {
  switch (action.type) {
    case 'eventsLoaded':
      return { ...state, events: action.events, eventsStatus: 'ready', eventsError: null };
    case 'eventsFailed':
      return { ...state, eventsStatus: 'error', eventsError: action.error };

    // Theme changes deliberately leave every booking field untouched.
    case 'themeChanged':
      return { ...state, theme: action.theme };

    case 'eventSelected': {
      if (action.eventId === state.selectedEventId) return state;
      const selectedEvent = state.events.find((e) => e.id === action.eventId);
      const firstBookable = selectedEvent?.timeSlots.find((s) => s.isBookable) ?? null;
      // A different event invalidates the slot and any selections made for it.
      return {
        ...state,
        selectedEventId: action.eventId,
        selectedSlotId: firstBookable?.id ?? null,
        ...clearedSelection,
        view: 'browse',
        checkout: idleCheckout,
      };
    }
    case 'slotSelected':
      if (action.slotId === state.selectedSlotId) return state;
      return { ...state, selectedSlotId: action.slotId, ...clearedSelection, view: 'browse', checkout: idleCheckout };

    case 'availabilityLoading':
      return { ...state, availabilityStatus: 'loading', availabilityError: null };
    case 'availabilityLoaded': {
      // Drop quantities that no longer fit what the server says remains.
      const ticketQuantities: Record<number, number> = {};
      for (const ticket of action.availability.ticketTypes) {
        const quantity = Math.min(state.ticketQuantities[ticket.ticketTypeId] ?? 0, ticket.remaining);
        if (quantity > 0) ticketQuantities[ticket.ticketTypeId] = quantity;
      }
      return { ...state, availability: action.availability, ticketQuantities, availabilityStatus: 'ready' };
    }
    case 'seatingLoaded': {
      const available = new Set(action.availability.seats.filter((s) => s.status === 'available').map((s) => s.seatId));
      return {
        ...state,
        seatingChart: action.chart,
        seatingAvailability: action.availability,
        selectedSeatIds: state.selectedSeatIds.filter((id) => available.has(id)),
        availabilityStatus: 'ready',
      };
    }
    case 'availabilityFailed':
      return { ...state, availabilityStatus: 'error', availabilityError: action.error };
    case 'availabilityRefreshRequested':
      return { ...state, availabilityVersion: state.availabilityVersion + 1 };

    case 'ticketQuantityChanged': {
      const ticketQuantities = { ...state.ticketQuantities };
      if (action.quantity > 0) ticketQuantities[action.ticketTypeId] = action.quantity;
      else delete ticketQuantities[action.ticketTypeId];
      return { ...state, ticketQuantities, checkout: idleCheckout };
    }
    case 'seatToggled': {
      const selected = state.selectedSeatIds.includes(action.seatId)
        ? state.selectedSeatIds.filter((id) => id !== action.seatId)
        : [...state.selectedSeatIds, action.seatId];
      return { ...state, selectedSeatIds: selected, checkout: idleCheckout };
    }

    case 'reviewOpened':
      return {
        ...state,
        view: 'review',
        checkout: { ...idleCheckout, idempotencyKey: state.checkout.idempotencyKey ?? newIdempotencyKey() },
      };
    case 'reviewClosed':
      return { ...state, view: 'browse', checkout: { ...state.checkout, status: 'idle', error: null } };
    case 'checkoutSubmitting':
      return { ...state, checkout: { ...state.checkout, status: 'submitting', error: null } };
    case 'checkoutRedirecting':
      return { ...state, checkout: { ...state.checkout, status: 'redirecting', order: action.order } };
    case 'checkoutFailed':
      // A conflict means the selection no longer fits: go back, refresh counts, and use a fresh key next time.
      return action.conflict
        ? {
            ...state,
            view: 'browse',
            availabilityVersion: state.availabilityVersion + 1,
            checkout: { ...idleCheckout, status: 'error', error: action.error },
          }
        : { ...state, checkout: { ...state.checkout, status: 'error', error: action.error } };

    case 'returnVerifying':
      return {
        ...state,
        view: 'confirmation',
        checkout: { ...state.checkout, status: 'verifying', error: null, returnOrderId: action.orderId },
      };
    case 'returnVerified':
      return { ...state, view: 'confirmation', checkout: { ...state.checkout, status: 'idle', order: action.order } };

    case 'demoAvailabilityReset':
    case 'bookingReset':
      return {
        ...state,
        ...clearedSelection,
        view: 'browse',
        checkout: idleCheckout,
        availabilityVersion: state.availabilityVersion + 1,
      };
  }
}

const clearedSelection = {
  ticketQuantities: {},
  selectedSeatIds: [],
  availability: null,
  seatingChart: null,
  seatingAvailability: null,
  availabilityStatus: 'idle',
  availabilityError: null,
} satisfies Partial<AppState>;

export interface AppContextValue {
  state: AppState;
  dispatch: Dispatch<AppAction>;
  changeTheme: (theme: ThemeName) => Promise<void>;
  submitCheckout: () => Promise<void>;
  verifyReturn: (orderId: string, cancel: boolean) => Promise<void>;
  /** Leaves the confirmation (clears the order reference from the URL) and starts a new booking. */
  resetBooking: () => void;
}

export const AppContext = createContext<AppContextValue | null>(null);

export function useApp(): AppContextValue {
  const value = useContext(AppContext);
  if (!value) throw new Error('useApp must be used inside <AppProvider>.');
  return value;
}

/** Convenience selectors. */
export function selectedEvent(state: AppState): EventSummary | null {
  return state.events.find((e) => e.id === state.selectedEventId) ?? null;
}
import { useCallback, useEffect, useMemo, useReducer, useRef, type ReactNode } from 'react';
import { api, ApiError } from '../services/api';
import type { CreateOrderRequest, ThemeName } from '../types/api';
import { AppContext, appReducer, initialState, selectedEvent, type AppContextValue } from './appState';

function errorMessage(error: unknown): string {
  return error instanceof Error ? error.message : 'Something went wrong.';
}

/** Owns shared state (useReducer) and the async operations that update it. */
export function AppProvider({ children }: { children: ReactNode }) {
  const [state, dispatch] = useReducer(appReducer, initialState);

  // Initial load: events and the persisted theme.
  useEffect(() => {
    api.getEvents()
      .then((events) => dispatch({ type: 'eventsLoaded', events }))
      .catch((error: unknown) => dispatch({ type: 'eventsFailed', error: errorMessage(error) }));
    api.getTheme()
      .then((theme) => dispatch({ type: 'themeChanged', theme: theme.activeTheme }))
      .catch(() => undefined); // Keep the default theme if settings are unavailable.
  }, []);

  // Load availability whenever the selected slot changes or a refresh is requested.
  const event = selectedEvent(state);
  const eventId = event?.id ?? null;
  const registrationType = event?.registrationType ?? null;
  const { selectedSlotId, availabilityVersion } = state;
  useEffect(() => {
    if (eventId === null || selectedSlotId === null) return;
    let cancelled = false;
    dispatch({ type: 'availabilityLoading' });

    const load = async () => {
      try {
        if (registrationType === 'ReservedSeating') {
          const [chart, availability] = await Promise.all([
            api.getSeatingChart(eventId),
            api.getSeatingAvailability(eventId, selectedSlotId),
          ]);
          if (!cancelled) dispatch({ type: 'seatingLoaded', chart, availability });
        } else {
          const availability = await api.getAvailability(eventId, selectedSlotId);
          if (!cancelled) dispatch({ type: 'availabilityLoaded', availability });
        }
      } catch (error) {
        if (!cancelled) dispatch({ type: 'availabilityFailed', error: errorMessage(error) });
      }
    };
    void load();
    return () => {
      cancelled = true;
    };
  }, [eventId, registrationType, selectedSlotId, availabilityVersion]);

  const changeTheme = useCallback(
    async (theme: ThemeName) => {
      const previous = state.theme;
      dispatch({ type: 'themeChanged', theme });
      try {
        await api.setTheme(theme);
      } catch {
        dispatch({ type: 'themeChanged', theme: previous });
      }
    },
    [state.theme],
  );

  const submitCheckout = useCallback(async () => {
    const { selectedSlotId: slotId, checkout, ticketQuantities, selectedSeatIds } = state;
    if (slotId === null || checkout.idempotencyKey === null) return;

    const body: CreateOrderRequest =
      registrationType === 'ReservedSeating'
        ? { timeSlotId: slotId, seatIds: selectedSeatIds }
        : {
            timeSlotId: slotId,
            tickets: Object.entries(ticketQuantities).map(([ticketTypeId, quantity]) => ({
              ticketTypeId: Number(ticketTypeId),
              quantity,
            })),
          };

    dispatch({ type: 'checkoutSubmitting' });
    try {
      const order = await api.createOrder(body, checkout.idempotencyKey);
      const session = await api.startCheckout(order.id);
      dispatch({ type: 'checkoutRedirecting', order });
      window.location.assign(session.checkoutUrl); // Stripe-hosted Checkout (test mode)
    } catch (error) {
      const conflict = error instanceof ApiError && error.status === 409;
      dispatch({ type: 'checkoutFailed', error: errorMessage(error), conflict });
    }
  }, [state, registrationType]);

  // Only the most recent verification may update state, so a slow earlier response
  // (e.g. a double click on "Check again") can never overwrite a newer result.
  const latestVerification = useRef(0);
  const verifyReturn = useCallback(async (orderId: string, cancel: boolean) => {
    const requestNumber = ++latestVerification.current;
    dispatch({ type: 'returnVerifying', orderId });
    try {
      const order = await api.confirmOrder(orderId, cancel);
      if (requestNumber === latestVerification.current) dispatch({ type: 'returnVerified', order });
    } catch (error) {
      if (requestNumber === latestVerification.current) {
        dispatch({ type: 'checkoutFailed', error: errorMessage(error), conflict: false });
      }
    }
  }, []);

  // Returning from Stripe (or refreshing the confirmation page): the URL identifies the order,
  // and the server re-checks payment every time. The success/cancel flag is only a hint that the
  // buyer asked to cancel; it is dropped after first use so a refresh simply re-verifies.
  const returnHandled = useRef(false);
  useEffect(() => {
    if (returnHandled.current) return; // effects can run twice in development (StrictMode)
    returnHandled.current = true;
    const params = new URLSearchParams(window.location.search);
    const orderId = params.get('orderId');
    if (!orderId) return;
    const cancelRequested = params.get('checkout') === 'cancel';
    window.history.replaceState(null, '', `${window.location.pathname}?orderId=${encodeURIComponent(orderId)}`);
    void verifyReturn(orderId, cancelRequested);
  }, [verifyReturn]);

  const resetBooking = useCallback(() => {
    window.history.replaceState(null, '', window.location.pathname);
    dispatch({ type: 'bookingReset' });
  }, []);

  const value = useMemo<AppContextValue>(
    () => ({ state, dispatch, changeTheme, submitCheckout, verifyReturn, resetBooking }),
    [state, changeTheme, submitCheckout, verifyReturn, resetBooking],
  );

  return <AppContext.Provider value={value}>{children}</AppContext.Provider>;
}
import { Hero } from './components/Hero';
import { useEffect, useRef } from 'react';
import { SiteHeader } from './components/SiteHeader';
import { useApp } from './context/appState';
import { EventCalendar } from './features/EventCalendar';
import { EventDetails } from './features/EventDetails';
import { ExperienceCollection } from './features/ExperienceCollection';
import { OrderConfirmation } from './features/OrderConfirmation';
import { ReviewOrder } from './features/ReviewOrder';
import { DemoResetControl } from './features/DemoResetControl';

export function App() {
  const { state } = useApp();
  const previousView = useRef(state.view);

  // A new checkout screen must start at its heading, not inherit the calendar's scroll position.
  useEffect(() => {
    if (state.view !== 'browse') {
      window.scrollTo({ top: 0, behavior: 'instant' });
    } else if (previousView.current === 'review') {
      document.getElementById('booking')?.scrollIntoView({ block: 'start', behavior: 'instant' });
    }
    previousView.current = state.view;
  }, [state.view]);

  return (
    <>
      <a className="skip-link" href="#main-content">Skip to main content</a>
      <SiteHeader />
      <main className="page" id="main-content">
        {state.view === 'confirmation' ? (
          <OrderConfirmation />
        ) : state.view === 'review' ? (
          <ReviewOrder />
        ) : (
          <>
            <Hero />
            <ExperienceCollection />
            <section className="booking-section" id="booking" aria-labelledby="booking-heading">
              <div className="section-intro booking-intro">
                <div>
                  <p className="eyebrow">Your next good memory</p>
                  <h2 id="booking-heading">A date with the season.</h2>
                </div>
                <p>Select an event, choose a time,<br />and leave the everyday behind.</p>
              </div>
              <div className="booking-layout">
                <EventCalendar />
                <EventDetails />
              </div>
            </section>
          </>
        )}
      </main>
      <footer className="site-footer">
        <div className="footer-wordmark">Blevins / Pass</div>
        <p>A little closer to the season.<br />A little further from ordinary.</p>
        <div className="footer-meta">
          <span>Brushfire · Eastern time</span>
          <span>Demonstration · Stripe test payments only</span>
        </div>
        {import.meta.env.DEV && <DemoResetControl />}
      </footer>
    </>
  );
}

