import { selectedEvent, useApp } from '../context/appState';
import { formatCents, formatLongDate, formatTime } from '../services/format';
import { SeatMap } from './SeatMap';
import { SelectionSummary } from './SelectionSummary';
import { TicketSelector } from './TicketSelector';

export function EventDetails() {
  const { state, dispatch } = useApp();
  const event = selectedEvent(state);

  if (!event) {
    return (
      <section className="card booking-welcome">
        <p className="eyebrow">Something to look forward to</p>
        <h2>Your season.<br /><em>Your kind of escape.</em></h2>
        <p className="muted">Start with an event on the calendar. We’ll help you find a time, choose your tickets, and make it yours.</p>
        <ol className="booking-steps"><li><span>01</span> Pick an experience</li><li><span>02</span> Find your time</li><li><span>03</span> Make a memory</li></ol>
      </section>
    );
  }

  return (
    <section className="card event-details" aria-labelledby="event-heading">
      <div className="event-intro">
        <img src={/winter|snow|concert/i.test(event.name) ? '/images/alpine-luxury.jpg' : '/images/autumn-editorial.jpg'} alt="" className="event-art" width="1536" height="1024" loading="lazy" />
        <div>
          <p className="eyebrow">
            {event.registrationType === 'ReservedSeating' ? 'Reserved seating' : 'General admission'} · {event.venue}
          </p>
          <h2 id="event-heading">{event.name}</h2>
          <p>{event.description}</p>
          {event.fromPriceCents !== null && <p className="muted">From {formatCents(event.fromPriceCents)}</p>}
        </div>
      </div>

      <fieldset className="slot-picker">
        <legend>Choose a time (venue time, Eastern)</legend>
        <div className="slot-options">
          {event.timeSlots.map((slot) => (
            <button
              key={slot.id}
              type="button"
              className={`slot-option${state.selectedSlotId === slot.id ? ' selected' : ''}`}
              aria-pressed={state.selectedSlotId === slot.id}
              disabled={!slot.isBookable}
              onClick={() => dispatch({ type: 'slotSelected', slotId: slot.id })}
            >
              <span>{formatLongDate(slot.startUtc)}</span>
              <strong>
                {formatTime(slot.startUtc)} – {formatTime(slot.endUtc)}
              </strong>
            </button>
          ))}
        </div>
      </fieldset>

      {state.checkout.status === 'error' && state.view === 'browse' && (
        <p className="error" role="alert">
          {state.checkout.error}
        </p>
      )}

      {state.selectedSlotId === null ? (
        <p className="muted">This event has no bookable time slots.</p>
      ) : state.availabilityStatus === 'loading' && !state.availability && !state.seatingAvailability ? (
        <p className="muted">Loading availability…</p>
      ) : state.availabilityStatus === 'error' ? (
        <div className="error" role="alert">
          {state.availabilityError}{' '}
          <button type="button" className="link-button" onClick={() => dispatch({ type: 'availabilityRefreshRequested' })}>
            Retry
          </button>
        </div>
      ) : event.registrationType === 'ReservedSeating' ? (
        <SeatMap />
      ) : (
        <TicketSelector />
      )}

      <SelectionSummary />
    </section>
  );
}
import { useApp } from '../context/appState';
import { formatCents } from '../services/format';

const maxPerType = 20;

/** Ticket types for the selected slot with live remaining counts and quantity steppers. */
export function TicketSelector() {
  const { state, dispatch } = useApp();
  const availability = state.availability;
  if (!availability) return null;

  return (
    <div className="ticket-list">
      <h3>Tickets</h3>
      {availability.ticketTypes.map((ticket) => {
        const quantity = state.ticketQuantities[ticket.ticketTypeId] ?? 0;
        const limit = Math.min(ticket.remaining, maxPerType);
        const soldOut = ticket.remaining === 0;
        const setQuantity = (next: number) =>
          dispatch({ type: 'ticketQuantityChanged', ticketTypeId: ticket.ticketTypeId, quantity: Math.max(0, Math.min(next, limit)) });

        return (
          <div key={ticket.ticketTypeId} className={`ticket-row${soldOut ? ' sold-out' : ''}`}>
            <div>
              <strong>{ticket.name}</strong> <span className="price">{formatCents(ticket.priceCents)}</span>
              <p className="muted small">{ticket.description}</p>
              <p className={`remaining${ticket.remaining <= 3 ? ' low' : ''}`}>
                {soldOut ? 'Sold out' : `${ticket.remaining} of ${ticket.capacity} left`}
              </p>
            </div>
            <div className="stepper" role="group" aria-label={`${ticket.name} quantity`}>
              <button type="button" aria-label={`Fewer ${ticket.name}`} disabled={quantity === 0} onClick={() => setQuantity(quantity - 1)}>
                −
              </button>
              <output aria-live="polite">{quantity}</output>
              <button type="button" aria-label={`More ${ticket.name}`} disabled={quantity >= limit} onClick={() => setQuantity(quantity + 1)}>
                +
              </button>
            </div>
          </div>
        );
      })}
    </div>
  );
}
import type { AppState } from '../context/appState';

export interface SelectionLine {
  key: string;
  description: string;
  quantity: number;
  unitPriceCents: number;
}

/**
 * Display-only summary of the current selection. The server re-prices everything when the order
 * is created; these numbers are never sent as payment amounts.
 */
export function selectionLines(state: AppState): SelectionLine[] {
  if (state.seatingChart && state.selectedSeatIds.length > 0) {
    return state.seatingChart.sections.flatMap((section) =>
      section.seats
        .filter((seat) => state.selectedSeatIds.includes(seat.id))
        .map((seat) => ({
          key: `seat-${seat.id}`,
          description: `${section.name} · Row ${seat.row}, Seat ${seat.seatNumber} (${seat.label})`,
          quantity: 1,
          unitPriceCents: section.priceCents,
        })),
    );
  }
  if (!state.availability) return [];
  return state.availability.ticketTypes
    .filter((ticket) => (state.ticketQuantities[ticket.ticketTypeId] ?? 0) > 0)
    .map((ticket) => ({
      key: `ticket-${ticket.ticketTypeId}`,
      description: ticket.name,
      quantity: state.ticketQuantities[ticket.ticketTypeId] ?? 0,
      unitPriceCents: ticket.priceCents,
    }));
}

export function selectionTotal(lines: SelectionLine[]): number {
  return lines.reduce((sum, line) => sum + line.unitPriceCents * line.quantity, 0);
}
import { useApp } from '../context/appState';
import { formatCents } from '../services/format';
import { selectionLines, selectionTotal } from './selection';

export function SelectionSummary() {
  const { state, dispatch } = useApp();
  const lines = selectionLines(state);
  const isSeating = state.seatingChart !== null && state.availability === null;

  return (
    <aside className="summary" aria-live="polite">
      <h3>Your selection</h3>
      {lines.length === 0 ? (
        <p className="muted">{isSeating ? 'Select seats on the chart.' : 'Choose ticket quantities above.'}</p>
      ) : (
        <ul>
          {lines.map((line) => (
            <li key={line.key}>
              <span>
                {line.quantity} × {line.description}
              </span>
              <span>{formatCents(line.unitPriceCents * line.quantity)}</span>
              {line.key.startsWith('seat-') && (
                <button
                  type="button"
                  className="link-button"
                  aria-label={`Remove ${line.description}`}
                  onClick={() => dispatch({ type: 'seatToggled', seatId: Number(line.key.slice(5)) })}
                >
                  Remove
                </button>
              )}
            </li>
          ))}
        </ul>
      )}
      <div className="summary-total">
        <span>Total</span>
        <strong>{formatCents(selectionTotal(lines))}</strong>
      </div>
      <button type="button" className="primary" disabled={lines.length === 0} onClick={() => dispatch({ type: 'reviewOpened' })}>
        Review order
      </button>
    </aside>
  );
}
import { useState } from 'react';
import { useApp } from '../context/appState';
import { api } from '../services/api';
import type { DemoResetResult } from '../types/api';

type ResetPhase = 'idle' | 'confirming' | 'running' | 'done' | 'failed';

/**
 * Development/demo tool in the footer. Rendered only by the Vite dev server (import.meta.env.DEV);
 * the API separately requires Development mode, an opt-in setting and a loopback caller.
 */
export function DemoResetControl() {
  const { resetBooking, dispatch } = useApp();
  const [phase, setPhase] = useState<ResetPhase>('idle');
  const [message, setMessage] = useState('');
  const [details, setDetails] = useState<DemoResetResult | null>(null);

  const runReset = async () => {
    setPhase('running');
    setMessage('Resetting… checking Stripe and restoring availability.');
    setDetails(null);
    try {
      const result = await api.resetDemo();
      if (result.completed) {
        resetBooking(); // clears selections/checkout and the URL order reference; theme and events stay
        dispatch({ type: 'demoAvailabilityReset' });
        setPhase('done');
        setMessage(summarize(result));
      } else {
        setPhase('failed');
        setMessage(result.message);
        setDetails(result); // keep per-order outcomes so the owner can see what already happened at Stripe
      }
    } catch (error) {
      setPhase('failed');
      setMessage(error instanceof Error ? error.message : 'Reset failed.');
    }
  };

  return (
    <div className="demo-reset" aria-label="Development tool">
      <span className="demo-reset-label">Development tool</span>
      {phase === 'confirming' ? (
        <div className="demo-reset-confirm" role="group" aria-labelledby="demo-reset-explainer">
          <p id="demo-reset-explainer">
            Restore all ticket and seat availability, expire unpaid checkouts, and refund every completed Stripe test
            purchase made in this app. Order history is kept.
          </p>
          <div className="demo-reset-actions">
            <button type="button" onClick={() => setPhase('idle')}>
              Cancel
            </button>
            <button type="button" className="demo-reset-go" onClick={() => void runReset()}>
              Reset and refund
            </button>
          </div>
        </div>
      ) : (
        <button type="button" className="demo-reset-button" disabled={phase === 'running'} onClick={() => setPhase('confirming')}>
          {phase === 'running' ? 'Resetting…' : 'Reset demo availability'}
        </button>
      )}
      <p className={`demo-reset-status${phase === 'failed' ? ' failed' : ''}`} role="status" aria-live="polite">
        {message}
      </p>
      {details && (details.refundedOrders.length > 0 || details.blockers.length > 0) && (
        <ul className="demo-reset-details">
          {details.refundedOrders.map((r) => (
            <li key={`r-${r.orderId}`}>
              Order {r.orderId.slice(0, 8)}: {statusLabel(r.providerStatus)} ({r.refundIds.join(', ') || 'no refund id'})
            </li>
          ))}
          {details.blockers.map((b) => (
            <li key={`b-${b.orderId}`}>
              Order {b.orderId.slice(0, 8)}: {b.reason}
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

function statusLabel(providerStatus: string): string {
  if (providerStatus === 'refunded') return 'refund completed at Stripe';
  if (providerStatus === 'refund_pending') return 'refund pending at Stripe (not counted)';
  return 'refund incomplete (not counted)';
}

function summarize(result: DemoResetResult): string {
  const refunds = result.refundedOrders.length;
  return `Availability restored. ${refunds} test purchase${refunds === 1 ? '' : 's'} refunded, ${result.releasedPendingOrders} unpaid checkout${result.releasedPendingOrders === 1 ? '' : 's'} closed.`;
}
