        Assert.Equal(25, await LivePeopleAsync(ride));
    }

    [Fact]
    public async Task Cancelling_an_offer_or_letting_the_accepted_order_lapse_passes_places_on()
    {
        var (ride, filler) = await SoldOutHayrideAsync();
