import { useCallback, useEffect, useState } from 'react';
import { useApp } from '../context/appState';
import { api } from '../services/api';
import { formatVenueDateTime } from '../services/format';
import type { WaitlistCustomerStatus, WaitlistStatus } from '../types/api';

const headings: Record<WaitlistCustomerStatus, string> = {
  Waiting: 'You’re on the waitlist',
  OfferPendingContact: 'Places are being set aside for you',
  OfferAvailable: 'Your tickets are ready to buy',
  CheckoutStarted: 'Checkout started',
  Purchased: 'Purchased — you’re booked',
  Expired: 'This offer has expired',
  Cancelled: 'You left the waitlist',
  Lapsed: 'This offer was not completed',
  Refunded: 'This test purchase was refunded',
};

/** Private status page reached from a ?waitlist= link. Status always comes from the server. */
export function WaitlistStatusView() {
  const { state, resetBooking } = useApp();
  const reference = state.waitlistReference;
  const [entry, setEntry] = useState<WaitlistStatus | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  const load = useCallback(async () => {
    if (!reference) return;
    try {
      setEntry(await api.getWaitlist(reference));
      setError(null);
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : 'Could not load this waitlist entry.');
    }
  }, [reference]);

  useEffect(() => {
    void load();
  }, [load]);

  // Accepting is retry-safe on the server (same order, same Stripe session), so a double click is harmless.
  const buy = async () => {
    if (!reference) return;
    setBusy(true);
    setError(null);
    try {
      const order = await api.acceptWaitlistOffer(reference);
      const session = await api.startCheckout(order.id);
      window.location.assign(session.checkoutUrl); // Stripe-hosted Checkout (test mode)
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : 'Could not start checkout.');
      setBusy(false);
      void load();
    }
  };

  const leave = async () => {
    if (!reference) return;
    setBusy(true);
    try {
      setEntry(await api.cancelWaitlist(reference));
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : 'Could not leave the waitlist.');
    } finally {
      setBusy(false);
    }
  };

  if (!entry) {
    return (
      <section className="card" aria-busy={!error}>
        <h2>{error ? 'Waitlist entry unavailable' : 'Loading your waitlist status…'}</h2>
        {error && <p className="error" role="alert">{error}</p>}
        <button type="button" onClick={resetBooking}>
          Back to events
        </button>
      </section>
    );
  }

  return (
    <section className="card confirmation" aria-labelledby="waitlist-status-heading">
      <p className="eyebrow">Waitlist · not a ticket until purchased</p>
      <h2 id="waitlist-status-heading">{headings[entry.status]}</h2>
      <StatusExplanation entry={entry} />
      {error && <p className="error" role="alert">{error}</p>}

      <dl className="order-facts">
        <dt>Event</dt>
        <dd>{entry.eventName}</dd>
        <dt>When (venue time)</dt>
        <dd>{formatVenueDateTime(entry.slotStartUtc)}</dd>
        <dt>Requested</dt>
        <dd>{entry.items.map((item) => `${item.quantity} × ${item.description}`).join(', ')}</dd>
        {entry.offerExpiresUtc && (
          <>
            <dt>Offer held until</dt>
            <dd>{formatVenueDateTime(entry.offerExpiresUtc)}</dd>
          </>
        )}
      </dl>

      <div className="actions">
        {entry.canAccept && (
          <button type="button" className="primary" disabled={busy} onClick={() => void buy()}>
            {busy ? 'Opening checkout…' : 'Buy these tickets'}
          </button>
        )}
        {entry.status === 'CheckoutStarted' && entry.orderId && (
          <a className="button primary" href={`/?orderId=${entry.orderId}`}>
            Check payment status
          </a>
        )}
        {entry.canCancel && (
          <button type="button" disabled={busy} onClick={() => void leave()}>
            Leave the waitlist
          </button>
        )}
        <button type="button" onClick={() => void load()} disabled={busy}>
          Refresh status
        </button>
        <button type="button" onClick={resetBooking}>
          Back to events
        </button>
      </div>
    </section>
  );
}

function StatusExplanation({ entry }: { entry: WaitlistStatus }) {
  switch (entry.status) {
    case 'Waiting':
      return (
        <p>
          You are number {entry.positionInLine} in line. Nothing has been charged and no payment details were taken. If
          places open up, the organizer will contact you personally.
        </p>
      );
    case 'OfferPendingContact':
      return <p>Places are reserved for your group. The organizer will contact you; you can buy once they have.</p>;
    case 'OfferAvailable':
      return <p>The organizer has contacted you. Buy before the offer ends, or the places go to the next person in line. You are charged only when you complete checkout.</p>;
    case 'CheckoutStarted':
      return <p>Your order was created from this offer. Finish or check your payment below.</p>;
    case 'Purchased':
      return <p>Payment verified. Your order reference is <span className="mono">{entry.orderId}</span>.</p>;
    case 'Expired':
      return <p>The offer ran out before purchase, so the places were passed to the next person in line. No payment was taken.</p>;
    case 'Lapsed':
      return <p>Checkout was not completed, so the places were passed on. No payment was taken.</p>;
    case 'Cancelled':
      return <p>This waitlist entry is closed. No payment was taken.</p>;
    case 'Refunded':
      return <p>This Stripe test-mode purchase was refunded by a development demo reset.</p>;
  }
}

import { useCallback, useEffect, useState } from 'react';
import { useApp } from '../context/appState';
import { api } from '../services/api';
import { formatVenueDateTime } from '../services/format';
import type { OperatorDeparture, OperatorStatus, OperatorWaitlistEntry } from '../types/api';

const statusLabels: Record<OperatorStatus, string> = {
  Queued: 'Queued — waiting for places',
  OfferReadyToNotify: 'Places reserved — contact this customer, then mark notified',
  ManuallyNotified: 'Manually notified — customer may buy',
  CheckoutStarted: 'Customer started checkout',
  Purchased: 'Purchased (payment verified)',
  Expired: 'Offer expired — places passed on',
  Cancelled: 'Cancelled',
  Lapsed: 'Checkout not completed — places passed on',
  Refunded: 'Test purchase refunded by demo reset',
};

/**
 * Development-only local operator page (?operator, Vite dev server only). This app sends no messages:
 * the owner contacts each customer personally, then records it here. Contact details and private links
 * appear only on this page, which the API serves only to a loopback Development caller.
 */
export function OperatorOutbox() {
  const { resetBooking } = useApp();
  const [entries, setEntries] = useState<OperatorWaitlistEntry[]>([]);
  const [departures, setDepartures] = useState<OperatorDeparture[]>([]);
  const [message, setMessage] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  const load = useCallback(async () => {
    try {
      const [outbox, slots] = await Promise.all([api.operator.getOutbox(), api.operator.getDepartures()]);
      setEntries(outbox);
      setDepartures(slots);
      setError(null);
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : 'Operator tools are unavailable.');
    }
  }, []);

  useEffect(() => {
    void load();
  }, [load]);

  const run = async (action: () => Promise<void>, done: string) => {
    setError(null);
    setMessage(null);
    try {
      await action();
      setMessage(done);
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : 'The change failed.');
    }
    await load();
  };

  return (
    <section className="card operator" aria-labelledby="operator-heading">
      <p className="eyebrow">Development tool · local owner only</p>
      <h2 id="operator-heading">Waitlist outbox</h2>
      <p className="muted">
        Nothing here sends email. For each “Places reserved” row, contact the customer yourself (copy the private link
        into your own message), then press “Mark notified”. Only then can they buy. Offers expire automatically.
      </p>
      {message && <p role="status">{message}</p>}
      {error && <p className="error" role="alert">{error}</p>}
      <div className="actions">
        <button type="button" onClick={() => void load()}>
          Refresh
        </button>
        <button type="button" onClick={resetBooking}>
          Back to events
        </button>
      </div>

      {entries.length === 0 ? (
        <p className="muted">No one is on a waitlist.</p>
      ) : (
        <ol className="operator-list">
          {entries.map((entry) => (
            <li key={entry.reference} className={`operator-entry status-${entry.operatorStatus}`}>
              <p>
                <strong>#{entry.queueNumber}</strong> · {entry.eventName} · {formatVenueDateTime(entry.slotStartUtc)}
              </p>
              <p className="operator-status">{statusLabels[entry.operatorStatus]}</p>
              <p>
                {entry.items.map((item) => `${item.quantity} × ${item.description}`).join(', ')} · {entry.customerEmail}
              </p>
              {entry.offerExpiresUtc && ['OfferReadyToNotify', 'ManuallyNotified'].includes(entry.operatorStatus) && (
                <p className="muted small">Offer ends {formatVenueDateTime(entry.offerExpiresUtc)}</p>
              )}
              <p className="small">
                Private link: <span className="mono">{entry.privateLink}</span>
              </p>
              {entry.operatorStatus === 'OfferReadyToNotify' && (
                <button
                  type="button"
                  className="primary"
                  onClick={() => void run(() => api.operator.markNotified(entry.reference), `Recorded manual notification for #${entry.queueNumber}.`)}
                >
                  Mark notified (I contacted them)
                </button>
              )}
            </li>
          ))}
        </ol>
      )}

      <h3>Open more places</h3>
      <p className="muted small">Raise a departure’s limits; the waitlist claims new places first, in order. Limits can only go up.</p>
      {departures.map((departure) => (
        <CapacityForm
          key={departure.timeSlotId}
          departure={departure}
          onSubmit={(sharedCapacity, typeCapacities) =>
            run(
              () =>
                api.operator.increaseCapacity(departure.timeSlotId, {
                  sharedCapacity,
                  ticketTypes: typeCapacities,
                }),
              `Capacity updated for ${departure.eventName}.`,
            )
          }
        />
      ))}
    </section>
  );
}

interface CapacityFormProps {
  departure: OperatorDeparture;
  onSubmit: (sharedCapacity: number | null, typeCapacities: { ticketTypeId: number; capacity: number }[]) => Promise<void>;
}

function CapacityForm({ departure, onSubmit }: CapacityFormProps) {
  const [shared, setShared] = useState(departure.sharedCapacity?.toString() ?? '');
  const [types, setTypes] = useState<Record<number, string>>(
    Object.fromEntries(departure.ticketTypes.map((t) => [t.ticketTypeId, t.capacity.toString()])),
  );

  const submit = () => {
    const sharedValue = shared.trim() === '' ? null : Number(shared);
    const changed = departure.ticketTypes
      .filter((t) => Number(types[t.ticketTypeId]) !== t.capacity)
      .map((t) => ({ ticketTypeId: t.ticketTypeId, capacity: Number(types[t.ticketTypeId]) }));
    void onSubmit(sharedValue === departure.sharedCapacity ? null : sharedValue, changed);
  };

  return (
    <fieldset className="capacity-form">
      <legend>
        {departure.eventName} · {formatVenueDateTime(departure.startUtc)}
      </legend>
      <p className="small muted">
        {departure.sharedCommitted} held or sold
        {departure.sharedCapacity !== null ? ` of ${departure.sharedCapacity} shared places` : ''} · {departure.waitingCount} waiting
      </p>
      <label>
        Shared limit
        <input type="number" min={1} value={shared} onChange={(event) => setShared(event.target.value)} />
      </label>
      {departure.ticketTypes.map((ticket) => (
        <label key={ticket.ticketTypeId}>
          {ticket.name} ({ticket.reserved + ticket.sold} held or sold)
          <input
            type="number"
            min={1}
            value={types[ticket.ticketTypeId] ?? ''}
            onChange={(event) => setTypes({ ...types, [ticket.ticketTypeId]: event.target.value })}
          />
        </label>
      ))}
      <button type="button" onClick={submit}>
        Save capacity
      </button>
    </fieldset>
  );
}

