    assert.equal(await page.locator('.experience-link').count(), 6);
    for (const theme of ['Fall', 'Winter']) {
      await chooseTheme(theme);
      await page.screenshot({ path: new URL(`${theme.toLowerCase()}-${width}.png`, output).pathname.replace(/^\/(\w:)/, '$1') });
