/// </summary>
public async Task PromoteAsync(int timeSlotId, CancellationToken cancellationToken)
{
    await ExpireOffersAsync(timeSlotId, cancellationToken);
    var slotStart = await db.TimeSlots.AsNoTracking().Where(s => s.Id == timeSlotId).Select(s => s.StartUtc).FirstAsync(cancellationToken);
    if (slotStart <= UtcNow)
    {
        return;
    }

    while (true)
    {
        var head = await db.WaitlistEntries.AsNoTracking().Include(w => w.Items)
            .Where(w => w.TimeSlotId == timeSlotId && w.Status == WaitlistStatus.Waiting)
            .OrderBy(w => w.Id)
            .FirstOrDefaultAsync(cancellationToken);
        if (head is null)
        {
            return;
        }

        var now = UtcNow;
        await using var transaction = await db.Database.BeginTransactionAsync(cancellationToken);
        try
        {
            await inventory.HoldTicketsAsync(timeSlotId, head.Items.OrderBy(i => i.TicketTypeId).Select(i => (i.TicketTypeId, i.Quantity, "requested")));
        }
        catch (BookingException)
        {
            // Strict head-of-line: the oldest group does not fit yet, so nobody behind it is offered.
            await transaction.RollbackAsync(CancellationToken.None);
            return;
        }

        var flipped = await db.WaitlistEntries
            .Where(w => w.Id == head.Id && w.Status == WaitlistStatus.Waiting)
            .ExecuteUpdateAsync(setters => setters
                .SetProperty(w => w.Status, WaitlistStatus.Offered)
                .SetProperty(w => w.OfferedUtc, now)
                .SetProperty(w => w.OfferExpiresUtc, now.Add(OfferLifetime)), cancellationToken);
        if (flipped != 1)
        {
            // Another request promoted or cancelled this entry first; undo our hold and look again.
            await transaction.RollbackAsync(CancellationToken.None);
            continue;
        }
        await transaction.CommitAsync(cancellationToken);
        logger.LogInformation("Waitlist entry {EntryId} offered places on time slot {TimeSlotId}", head.Id, timeSlotId);
    }
}

