// Rendered partial-sellout check (scratch script): Orchard Cider Tasting, VIP sold out, GA available.
import assert from 'node:assert/strict';
import { mkdir, writeFile } from 'node:fs/promises';
const { chromium } = await import(process.env.PLAYWRIGHT_MODULE);
const origin = 'http://127.0.0.1:5174';
const out = 'C:/Dev/project-brushfire/ai-sessions/PHASE-2/evidence/ui-partial-sellout/';
await mkdir(out, { recursive: true });
const api = async (path, init) => {
  const r = await fetch(origin + path, { ...init, headers: { 'Content-Type': 'application/json', ...init?.headers } });
  if (!r.ok) throw new Error(`${path} ${r.status} ${await r.text()}`);
  return r.json();
};
const events = await api('/api/events');
const cider = events.find((e) => e.name === 'Orchard Cider Tasting');
const slot = cider.timeSlots.find((s) => s.isBookable);
const avail = await api(`/api/events/${cider.id}/availability?timeSlotId=${slot.id}`);
const vip = avail.ticketTypes.find((t) => t.name === 'VIP');
await api('/api/orders', { method: 'POST', headers: { 'Idempotency-Key': `partial-vip-${slot.id}` }, body: JSON.stringify({ timeSlotId: slot.id, tickets: [{ ticketTypeId: vip.ticketTypeId, quantity: 2 }] }) });

const browser = await chromium.launch({ channel: 'chrome', headless: true });
const results = [];
const errors = [];
try {
  for (const width of [1440, 390]) {
    const page = await (await browser.newContext({ viewport: { width, height: 900 } })).newPage();
    page.on('pageerror', (e) => errors.push(e.message));
    await page.goto(origin);
    await page.getByRole('button', { name: /Orchard Cider Tasting/ }).first().click();
    await page.getByRole('heading', { name: 'Join VIP waitlist' }).waitFor();
    assert.equal(await page.getByRole('heading', { name: 'Join General Admission waitlist' }).count(), 0);
    assert.ok(await page.getByRole('button', { name: 'More General Admission', exact: true }).isEnabled());
    if (width === 1440) {
      await page.getByRole('button', { name: 'More VIP on waitlist' }).click();
      await page.getByLabel('Email for the organizer to contact you').fill('partial-check@example.com');
      await page.getByRole('button', { name: 'Join waitlist (no charge)' }).click();
      await page.getByRole('heading', { name: 'You’re on the waitlist' }).waitFor();
      await page.reload();
      await page.getByRole('button', { name: /Orchard Cider Tasting/ }).first().click();
      await page.getByRole('button', { name: 'More General Admission', exact: true }).waitFor();
    }
    // GA remains selectable and purchasable after the VIP request joined.
    await page.getByRole('button', { name: 'More General Admission', exact: true }).click();
    assert.equal(await page.locator('.summary li').count(), 1);
    const overflow = await page.evaluate(() => document.documentElement.scrollWidth - innerWidth);
    assert.ok(overflow <= 1);
    await page.locator('#booking').screenshot({ path: `${out}cider-vip-waitlist-${width}.png` });
    results.push({ width, vipWaitlistShown: true, gaPurchasableInUi: true, overflow });
  }
  const after = await api(`/api/events/${cider.id}/availability?timeSlotId=${slot.id}`);
  const gaAfter = after.ticketTypes.find((t) => t.name === 'General Admission');
  const order = await api('/api/orders', { method: 'POST', headers: { 'Idempotency-Key': `partial-ga-${slot.id}` }, body: JSON.stringify({ timeSlotId: slot.id, tickets: [{ ticketTypeId: gaAfter.ticketTypeId, quantity: 2 }] }) });
  results.push({ vipWaiting: after.ticketTypes.find((t) => t.name === 'VIP').waitlistWaiting, gaRemainingBefore: gaAfter.remaining, gaOrderStatus: order.status });
  assert.equal(order.status, 'PendingCheckout');
  assert.deepEqual(errors, []);
} finally {
  await browser.close();
  await writeFile(`${out}results.json`, JSON.stringify({ checkedAt: new Date().toISOString(), results, errors }, null, 2));
}
console.log(JSON.stringify(results));

