const fs = require('fs');
process.chdir('C:/Dev/project-brushfire');
function rep(file, pairs) {
  let s = fs.readFileSync(file, 'utf8');
  for (const [a, b] of pairs) {
    if (!s.includes(a)) throw new Error(`missing in ${file}: ${a.slice(0, 70)}`);
    s = s.replace(a, b);
  }
  fs.writeFileSync(file, s);
}
const policy = 'On **shared-capacity** departures (hayride) the queue is departure-wide: if the oldest waiting group does not fit, nobody behind it is offered, and while anyone is `Waiting` all public sales for that departure are closed. On **independent-capacity** departures (`SharedCapacity` null, e.g. cider VIP/GA) FIFO applies **per ticket type**: a waiter blocks public sales, offers and new joins only for the type(s) it requested, so a VIP waiter never blocks General Admission. New requests there name exactly one type; older multi-type entries stay linked, are offered all-or-nothing, and block every type they include so overlapping requests cannot pass them.';

rep('docs/contracts/booking-rules.md', [
  ['The UI offers joining on sold-out/queued departures; the current API does **not** enforce sold-out eligibility. A direct join can immediately reserve an available selection for the offer window. This inventory-squatting limitation is reviewed and unresolved, not an overselling result.',
   'The API refuses joins for selections that can be bought now (F1, below). The UI offers a join form for the whole departure when a shared-capacity departure is full or queued, and a per-type "Join {type} waitlist" form under each unavailable type on independent-capacity departures.'],
  ['- **Queue order** = entry id (first come, first served) per departure. **Strict head-of-line:** if the oldest waiting group does not fit, nobody behind it is offered, even a smaller group. While anyone is `Waiting`, public sales for that departure are closed (`409 waitlist_active`; availability shows 0), so new buyers cannot jump the line. This rule is part of the public hold UPDATE itself (`NOT EXISTS` a `Waiting` entry for the departure)',
   `- **Queue order** = entry id (first come, first served). ${policy} Blocked public holds get \`409 waitlist_active\` and availability shows 0 for the blocked type(s). This rule is part of the public hold UPDATE itself (\`NOT EXISTS\` a competing \`Waiting\` entry)`],
  ['when nobody is `Waiting` for the departure and the whole group fits', 'when no competing request is `Waiting` (anyone on a shared departure; the same type otherwise) and the whole group fits'],
]);
rep('docs/contracts/api-contract.md', [
  ['ticketTypes: [{ ticketTypeId, name, description, priceCents, capacity, remaining }], sharedCapacity, sharedRemaining, waitlistWaiting }`', 'ticketTypes: [{ ticketTypeId, name, description, priceCents, capacity, remaining, waitlistWaiting }], sharedCapacity, sharedRemaining, waitlistWaiting }`'],
  ['everything is 0 while anyone is waiting |', 'on shared departures everything is 0 while anyone is waiting; on independent departures only the waited-for types are 0 (per-type `waitlistWaiting`) |'],
  ['`409 tickets_available` when nobody is waiting and the whole group can be bought now (nothing is created).', '`409 tickets_available` when no competing request is waiting and the whole group can be bought now (nothing is created). Independent-capacity departures accept one ticket type per new request (400 otherwise).'],
]);
rep('README.md', [[
  '- **First come, first served, strictly.** If the group at the front does not fit, smaller groups behind it wait too. While anyone is waiting, public sales for that departure stay closed.',
  '- **First come, first served.** On the hayride (shared limit) the queue covers the whole departure: if the group at the front does not fit, smaller groups wait too, and public sales stay closed while anyone waits. On departures without a shared limit (e.g. cider tasting) the queue is per ticket type: "Join VIP waitlist" appears under a sold-out VIP row, and General Admission stays on sale.',
]]);
rep('docs/phase-2/WAITLIST-GUIDE.md', [
  ['1. Select a future General Admission event and departure. The UI shows **Join waitlist (no charge)** when all ticket types have zero available or a queue is already waiting. Reserved seating is excluded.',
   '1. Select a future General Admission event and departure. On a shared-capacity departure (hayride) the UI shows one **Join the waitlist** form when it is full or a queue exists. On departures without a shared limit, each unavailable ticket type shows its own **Join {type} waitlist** form (one type per request) while other types stay on sale. Closed/past departures show no form and the API rejects them. Reserved seating is excluded.'],
  ['- **FIFO, strict head-of-line:** the oldest waiting request is considered first. If its entire group does not fit, smaller groups behind it also wait. All public purchases for that departure are blocked while anyone remains Waiting. This can intentionally leave places unused.',
   `- **FIFO (owner-approved policy):** the oldest competing request is considered first, and a request that does not fit holds back the requests behind it that compete with it. ${policy} Strict ordering can intentionally leave places unused.`],
  ['A direct request can immediately hold25 places without payment for24h. This is inventory squatting, not overselling. Proposed minimal change: reject a join when no waiting queue exists and the requested selection is currently purchasable; preserve atomic queue/inventory rules and add a regression. Operator cancellation is a separate optional enhancement. **Not implemented; owner decision pending.** |',
   'Was: a direct request could hold places without payment. **Implemented (final correction):** joins for currently purchasable selections are refused with `409 tickets_available` inside the join transaction. Operator cancellation remains not implemented. |'],
  ['| **Low: restricted UI entry conditions** | A group of3 cannot join through the UI when1 place remains unless a queue already exists. Proposed policy decision: retain sold-out-only UI, or later offer a waitlist when a requested selection cannot fit. |',
   '| **Low: restricted UI entry conditions** | **Partly addressed (owner-approved partial-sellout policy):** independent-capacity departures now offer a per-type waitlist for each unavailable type. On shared departures a group that cannot fit the remaining places still cannot join through the UI unless a queue exists. |'],
]);
console.log('ok');

